-- Current windowed companion compiler shape: one fact scan, no companion self-join.
-- psql -v account_id=46 -v date_start=2025-01-01 -v date_end=2026-10-29 -v analyze=false
-- Default EXPLAIN does not execute the aggregation. Analyze mode is opt-in, read-only,
-- and limited to 45 seconds; run it only during a quiet period.
\if :{?analyze}
\else
\set analyze false
\endif
BEGIN READ ONLY;
SET LOCAL statement_timeout = '45s';
\if :analyze
EXPLAIN (ANALYZE, BUFFERS, SETTINGS, FORMAT TEXT)
\else
EXPLAIN (COSTS, VERBOSE, SETTINGS, FORMAT TEXT)
\endif
WITH contract_observations AS MATERIALIZED (
SELECT wm.*,
 SUM(CASE WHEN LOWER(wc.name)='sessions' THEN 1 ELSE 0 END) OVER contract_grain AS _contract_weight_count_0,
 MAX(CASE WHEN LOWER(wc.name)='sessions' THEN wm.value END) OVER contract_grain AS _contract_weight_value_0
FROM metrics wm JOIN metric_configs wc ON wc.id=wm.metric_config_id
WHERE LOWER(wc.period)='daily'
 AND LOWER(wc.name) IN ('screenpageviews','sessions','bouncerate','bounce_rate','averagesessionduration','average_session_duration','totalrevenue','conversions')
 AND wc.channel IN (SELECT id FROM channels WHERE name='google_analytics')
 AND wc.channeled_account_id=:'account_id'
 AND wm.metric_date>=:'date_start' AND wm.metric_date<=:'date_end'
 AND wc.dimension_set_id IN (SELECT wi.dimension_set_id FROM dimension_set_items wi JOIN dimension_values wv ON wv.id=wi.dimension_value_id JOIN dimension_keys wk ON wk.id=wv.dimension_key_id WHERE LOWER(wk.name)='scope' AND wv.value='traffic_matrix')
WINDOW contract_grain AS (PARTITION BY wc.channel, wc.account_id, wc.channeled_account_id, wc.campaign_id, wc.channeled_campaign_id, wc.channeled_ad_group_id, wc.channeled_ad_id, wc.creative_id, wc.event_id, wc.channeled_event_id, wc.page_id, wc.post_id, wc.product_id, wc.customer_id, wc.order_id, wc.query_id, wc.country_id, wc.device_id, wc.dimension_set_id, wc.location_id, wc.state_id, wc.city_id, wm.metric_date))
SELECT COALESCE(dv_dim_landing_page.value, 'unknown') AS "dimensions.landing_page", SUM(CASE WHEN LOWER(mc.name) IN ('screenpageviews') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "screenPageViews", SUM(CASE WHEN LOWER(mc.name) IN ('sessions') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "sessions", CASE WHEN SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' AND (m._contract_weight_count_0 IS NULL OR m._contract_weight_count_0 <> 1 OR m._contract_weight_value_0 IS NULL OR m._contract_weight_value_0 < 0) THEN 1 ELSE 0 END) > 0 THEN NULL ELSE SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' THEN m.value * m._contract_weight_value_0 ELSE 0 END) / NULLIF(SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' THEN m._contract_weight_value_0 ELSE 0 END), 0) END AS "bounceRate", CASE WHEN SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' AND (m._contract_weight_count_0 IS NULL OR m._contract_weight_count_0 <> 1 OR m._contract_weight_value_0 IS NULL OR m._contract_weight_value_0 < 0) THEN 1 ELSE 0 END) > 0 THEN NULL ELSE SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' THEN m.value * m._contract_weight_value_0 ELSE 0 END) / NULLIF(SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' THEN m._contract_weight_value_0 ELSE 0 END), 0) END AS "averageSessionDuration", CASE WHEN COUNT(DISTINCT CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN mc.channeled_account_id END) > 1 AND (COUNT(DISTINCT CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN NULLIF(TRIM(m.metadata #>> '{ga4_report_quality,currencyCode}'), '') END) <> 1 OR MAX(CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' AND NULLIF(TRIM(m.metadata #>> '{ga4_report_quality,currencyCode}'), '') IS NULL THEN 1 ELSE 0 END) = 1) THEN 1 ELSE 0 END AS "_contract_currency_0", SUM(CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "totalRevenue", SUM(CASE WHEN LOWER(mc.name) IN ('conversions') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "conversions" FROM contract_observations m JOIN metric_configs mc ON m.metric_config_id = mc.id LEFT JOIN dimension_set_items dsi_dim_landing_page ON mc.dimension_set_id = dsi_dim_landing_page.dimension_set_id AND dsi_dim_landing_page.dimension_value_id IN ( SELECT sub_dv.id FROM dimension_values sub_dv JOIN dimension_keys sub_dk ON sub_dv.dimension_key_id = sub_dk.id WHERE LOWER(sub_dk.name) = 'landing_page' ) LEFT JOIN dimension_values dv_dim_landing_page ON dsi_dim_landing_page.dimension_value_id = dv_dim_landing_page.id LEFT JOIN dimension_set_items dsi_dim_filter_scope ON mc.dimension_set_id = dsi_dim_filter_scope.dimension_set_id AND dsi_dim_filter_scope.dimension_value_id IN ( SELECT sub_dv.id FROM dimension_values sub_dv JOIN dimension_keys sub_dk ON sub_dv.dimension_key_id = sub_dk.id WHERE LOWER(sub_dk.name) = 'scope' ) LEFT JOIN dimension_values dv_dim_filter_scope ON dsi_dim_filter_scope.dimension_value_id = dv_dim_filter_scope.id  WHERE mc.channel IN (SELECT id FROM channels WHERE name IN ('google_analytics')) AND m.metric_date >= :'date_start' AND m.metric_date <= :'date_end' AND mc.channeled_account_id = :'account_id' AND dv_dim_filter_scope.value = 'traffic_matrix' AND LOWER(mc.name) IN ('screenpageviews', 'sessions', 'bouncerate', 'bounce_rate', 'averagesessionduration', 'average_session_duration', 'totalrevenue', 'conversions') AND LOWER(mc.period) = 'daily' GROUP BY COALESCE(dv_dim_landing_page.value, 'unknown') ;
ROLLBACK;
